solution.solution.js:
function toHex(bytes) {
  return Array.from(bytes, b => b.toString(16).padStart(2, "0")).join(" ");
}

function fromHex(text) {
  const clean = text.replace(/\s+/g, "");
  if (clean.length % 2 !== 0 || /[^0-9a-fA-F]/.test(clean)) throw new SyntaxError("not hex: " + text);
  const out = new Uint8Array(clean.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(clean.slice(i * 2, i * 2 + 2), 16);
  return out;
}

unitTests:
test("toHex pads and separates", () => {
  checkEq(toHex(new Uint8Array([0, 255, 16])), "00 ff 10");
  checkEq(toHex(new Uint8Array([])), "");
});

test("fromHex gives a Uint8Array", () => {
  const b = fromHex("00 FF 10");
  check(b instanceof Uint8Array);
  checkEq(Array.from(b), [0, 255, 16]);
  checkEq(Array.from(fromHex("cafe")), [202, 254]);
});

test("round trip", () => {
  const bytes = new Uint8Array([1, 2, 3, 250]);
  checkEq(Array.from(fromHex(toHex(bytes))), [1, 2, 3, 250]);
});

test("bad hex throws", () => {
  checkThrows(() => fromHex("abc"), SyntaxError);
  checkThrows(() => fromHex("zz"), SyntaxError);
});

